sys_security_acl.script:
(function() {
    // Grant access to users with problem_manager or itil role
    // Adjust these roles based on your organization's needs

    if (gs.hasRole('problem_manager')) {
        return true;
    }

    if (gs.hasRole('itil')) {
        return true;
    }

    // Grant access to admin users (recommended)
    if (gs.hasRole('admin')) {
        return true;
    }

    // Deny access to all other users
    return false;
})();
